<?php
declare(strict_types=1);ini_set('session.save_path',__DIR__.'/../includes/runtime');set_time_limit(0);require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/helpers.php';require_once __DIR__.'/../includes/gemini_transport.php';
if(PHP_SAPI!=='cli')exit(1);$db=db();$rows=$db->query("SELECT l.id,l.display_order,l.title_si,l.content_si FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Civic Education' AND l.medium='Sinhala' AND l.display_order IN (3,4,5) AND l.title_si IS NOT NULL ORDER BY l.display_order")->fetch_all(MYSQLI_ASSOC);if(count($rows)!==3)throw new RuntimeException('Three Sinhala Civic lessons were not found.');$out=[];
foreach($rows as $row){$data=null;for($attempt=1;$attempt<=4&&!$data;$attempt++){$prompt="ශ්‍රී ලංකා 10 ශ්‍රේණිය පුරවැසි අධ්‍යාපනය පාඩම සඳහා පෙළපොත් උපුටනය පමණක් භාවිත කර කෙටි සිංහල Unicode MCQ හරියටම 30ක් සාදන්න. JSON array only; no markdown. Each object exactly keys question,a,b,c,d,correct,explanation. correct is a/b/c/d. සෑම ප්‍රශ්නයකටම විකල්ප 4ක් දෙන්න. පාඩම: {$row['title_si']}\n".mb_substr((string)$row['content_si'],0,12000);$payload=json_encode(['contents'=>[['parts'=>[['text'=>$prompt]]]],'generationConfig'=>['temperature'=>0.05,'maxOutputTokens'=>16000,'responseMimeType'=>'application/json']],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$r=gemini_http_json(GEMINI_API_BASE.rawurlencode(GEMINI_MODEL).':generateContent?key='.rawurlencode(GEMINI_API_KEY),['Content-Type: application/json'],$payload);if($r['status']!==200)continue;$body=json_decode($r['body'],true);$text='';foreach($body['candidates'][0]['content']['parts']??[] as $p)$text.=$p['text']??'';$candidate=json_decode($text,true);if(is_array($candidate)&&count($candidate)===30)$data=$candidate;}if(!$data)throw new RuntimeException("Lesson {$row['display_order']} did not return 30 questions after retries.");foreach($data as $q){if(!in_array($q['correct']??'',['a','b','c','d'],true))throw new RuntimeException('Invalid answer key.');foreach(['question','a','b','c','d','explanation'] as $k)if(trim((string)($q[$k]??''))==='')throw new RuntimeException("Missing $k");}$out[(string)$row['display_order']]=['title'=>$row['title_si'],'questions'=>$data];echo "Built lesson {$row['display_order']}\n";}
if(!is_dir(__DIR__.'/data'))mkdir(__DIR__.'/data',0775,true);file_put_contents(__DIR__.'/data/grade10-civic-lessons3-5.json',json_encode($out,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
